import { getAdminSession } from "../../../lib/auth";
import { prisma } from "../../../lib/prisma";

export async function GET() {
  const admin = await getAdminSession();

  if (!admin) {
    return Response.json({ error: "Unauthorized" }, { status: 401 });
  }

  const doctors = await prisma.doctor.findMany({
    include: {
      hospital: {
        select: {
          id: true,
          name: true,
        },
      },
    },
    orderBy: [{ id: "desc" }],
  });

  return Response.json({ doctors });
}

export async function POST(request) {
  try {
    const admin = await getAdminSession();

    if (!admin) {
      return Response.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await request.json();
    const hospitalId = Number(body.hospitalId);

    if (Number.isNaN(hospitalId)) {
      return Response.json({ error: "Valid hospital is required." }, { status: 400 });
    }

    const hospital = await prisma.hospital.findUnique({
      where: { id: hospitalId },
      select: { id: true },
    });

    if (!hospital) {
      return Response.json({ error: "Hospital not found." }, { status: 404 });
    }

    const doctor = await prisma.doctor.create({
      data: {
        name: body.name?.trim(),
        specialty: body.specialty?.trim(),
        experience: body.experience?.trim(),
        rating: Number(body.rating) || 0,
        reviews: Number(body.reviews) || 0,
        qualification: body.qualification?.trim(),
        college: body.college?.trim(),
        tags: Array.isArray(body.tags) ? body.tags : [],
        available: body.available?.trim(),
        conditions: Array.isArray(body.conditions) ? body.conditions : [],
        hospitalId,
      },
      include: {
        hospital: {
          select: {
            id: true,
            name: true,
          },
        },
      },
    });

    return Response.json({ doctor }, { status: 201 });
  } catch (error) {
    console.error("Create doctor API error:", error);
    return Response.json(
      { error: "Unable to create doctor right now." },
      { status: 500 }
    );
  }
}
